import { expect, test, uniqueName } from "../../fixtures";

const API_TIMEOUT_MS = 60_000;

type Extraction = {
  id: string;
  kind: string;
  fields: Record<string, { value: string | null; confidence: number }>;
};

async function waitForExtracted(
  reviewer: { get: (url: string) => Promise<any> },
  documentId: string,
): Promise<void> {
  const deadline = Date.now() + API_TIMEOUT_MS;
  while (Date.now() < deadline) {
    const response = await reviewer.get(`/api/documents/${documentId}`);
    expect(response.status()).toBe(200);
    const doc = await response.json();
    if (doc.status === "extracted") return;
    expect(doc.status, `document ${documentId} processing outcome`).not.toBe("failed");
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error(`document ${documentId} was not extracted within ${API_TIMEOUT_MS}ms`);
}

async function createVendorInReview(
  member: any,
  name: string,
  insuranceText: string,
): Promise<string> {
  const create = await member.post("/api/vendors", {
    data: { name, category: "services", contact_email: `ops.${Date.now().toString(36)}@example.test` },
  });
  expect(create.status()).toBe(201);
  const vendorId: string = (await create.json()).id;

  const uploads: Array<{ kind: string; buffer: Buffer; name: string }> = [
    { kind: "w9", buffer: Buffer.from("W-9 form, taxpayer name Test"), name: "w9.pdf" },
    {
      kind: "insurance_certificate",
      buffer: Buffer.from(insuranceText),
      name: "insurance.pdf",
    },
    { kind: "contract", buffer: Buffer.from("Master services contract"), name: "contract.pdf" },
  ];

  const documentIds: string[] = [];
  for (const upload of uploads) {
    const response = await member.post(`/api/vendors/${vendorId}/documents`, {
      multipart: {
        kind: upload.kind,
        file: { name: upload.name, mimeType: "application/pdf", buffer: upload.buffer },
      },
    });
    expect(response.status()).toBe(201);
    documentIds.push((await response.json()).id);
  }

  for (const documentId of documentIds) {
    await waitForExtracted(member, documentId);
  }

  const submit = await member.post(`/api/vendors/${vendorId}/submit`);
  expect(submit.status()).toBe(200);
  return vendorId;
}

test.describe("review queue ordering", () => {
  test(
    "lists the vendor with an unparsed insurance expiry first, ordered by lowest confidence",
    { tag: "@REV-03" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const unparsedName = uniqueName("REV03 Unparsed");
      const parsedName = uniqueName("REV03 Parsed");

      const unparsedVendorId = await createVendorInReview(
        member,
        unparsedName,
        "Certificate of insurance. Expiry: not legible on scan",
      );
      const parsedVendorId = await createVendorInReview(
        member,
        parsedName,
        "Certificate of insurance. Expiry: 2031-06-30",
      );

      // Act
      const response = await reviewer.get("/api/review-queue");

      // Assert
      expect(response.status()).toBe(200);
      const queue: Array<{
        vendor_id: string;
        lowest_confidence: number;
        extractions: Extraction[];
      }> = await response.json();

      const unparsedIndex = queue.findIndex((item) => item.vendor_id === unparsedVendorId);
      const parsedIndex = queue.findIndex((item) => item.vendor_id === parsedVendorId);
      expect(unparsedIndex, "unparsed-date vendor is in the queue").toBeGreaterThanOrEqual(0);
      expect(parsedIndex, "parsed-date vendor is in the queue").toBeGreaterThanOrEqual(0);
      expect(unparsedIndex).toBeLessThan(parsedIndex);

      for (let i = 1; i < queue.length; i++) {
        expect(
          queue[i - 1].lowest_confidence,
          `queue item ${i - 1} has lowest confidence <= item ${i}`,
        ).toBeLessThanOrEqual(queue[i].lowest_confidence);
      }

      const unparsedInsurance = queue[unparsedIndex].extractions.find(
        (e) => e.kind === "insurance_certificate",
      );
      expect(unparsedInsurance, "unparsed vendor has an insurance extraction").toBeDefined();
      const hasUnparsedExpiry = Object.values(unparsedInsurance!.fields).some(
        (field) => field.value === null,
      );
      expect(hasUnparsedExpiry, "unparsed vendor has a null expiry field").toBe(true);
    },
  );
});
